test('returns 0 for whitespace only', () => {
  assert.equal(sentenceCount('  \n\t  '), 0);
});

test('returns 0 for terminators with no words', () => {
  assert.equal(sentenceCount('... ?! . ! ?'), 0);
});

test('counts one sentence with a final period', () => {
  assert.equal(sentenceCount('The tide came in.'), 1);
});

test('counts one sentence with no terminator at all', () => {
  assert.equal(sentenceCount('The tide came in'), 1);
});

test('counts a trailing fragment after the last terminator', () => {
  assert.equal(sentenceCount('The tide came in. Then it left'), 2);
});

test('throws a TypeError naming the function for a non-string', () => {
  for (const bad of [undefined, null, 7, {}, ['One.']]) {
    assert.throws(() => sentenceCount(bad), (err) => {
      assert.ok(err instanceof TypeError);
      assert.ok(err.message.startsWith('sentenceCount:'));
      return true;
    });
  }
});

test('matches every row of the reference table', () => {
  for (const [text, expected] of CASES) {
    assert.equal(sentenceCount(text), expected, JSON.stringify(text));
  }
});

test('counts the hand-counted eight sentences in the multi-line passage', () => {
  assert.equal(sentenceCount(PASSAGE), 8);
});

test('does not end a sentence at a period inside a decimal, domain or dotted name', () => {
  assert.equal(sentenceCount('It cost 3.14 dollars.'), 1);
  assert.equal(sentenceCount('Visit example.com today. Then leave.'), 2);
  assert.equal(sentenceCount('The id is a.b.c and it works.'), 1);
});

test('does not end a sentence after a listed abbreviation', () => {
  for (const abbr of ['Mr', 'Mrs', 'Ms', 'Dr', 'Prof', 'St', 'Sr', 'Jr', 'vs', 'e.g', 'i.e']) {
    assert.equal(sentenceCount(`See ${abbr}. Smith now.`), 1, abbr);
  }
});

test('compares abbreviations without regard to case', () => {
  assert.equal(sentenceCount('See MR. Smith and dr. Jones today.'), 1);
  assert.equal(sentenceCount('Use tools, E.G. hammers, today.'), 1);
});

test('still ends a sentence at an abbreviation followed by a run of periods', () => {
  assert.equal(sentenceCount('Ask Mr... Then go.'), 2);
  assert.equal(sentenceCount('Who is Dr?! Then go.'), 2);
});

test('ends a sentence at a period after a word that is not an abbreviation', () => {
  assert.equal(sentenceCount('He met Bob. Then he left.'), 2);
});

test('treats a terminator run as a single terminator', () => {
  assert.equal(sentenceCount('Really?! Yes... Fine.'), 3);
});

test('ends a sentence at a terminator followed by closing quotes or brackets', () => {
  assert.equal(sentenceCount('He said "go." Then left.'), 2);
  assert.equal(sentenceCount('It ended (finally.) Then silence.'), 2);
  assert.equal(sentenceCount('Is it [true?] Maybe.'), 2);
});
